<?php
require_once dirname(__DIR__).'/config.php';
require_admin();
$conn=db(); $message=''; $error='';
$courseOptions=['Bachelor of Science in Information Technology (BSIT)','Bachelor of Science in Computer Science (BSCS)','Bachelor of Science in Information Systems (BSIS)','Bachelor of Science in Business Administration (BSBA)','Bachelor of Science in Accountancy (BSA)','Bachelor of Science in Hospitality Management (BSHM)','Bachelor of Science in Tourism Management (BSTM)','Bachelor of Science in Education (BSEd)','Bachelor of Elementary Education (BEEd)','Bachelor of Science in Criminology (BSCRIM)','Other'];
$yearOptions=['1st Year','2nd Year','3rd Year','4th Year'];
function format_student_name($value){return preg_replace_callback('/(^|[\s-])([a-z])/',function($match){return $match[1].strtoupper($match[2]);},strtolower(trim((string)$value)));}
function student_import_value($value){return trim((string)$value);}
function student_import_course($value,$courseOptions){
  $key=strtoupper(preg_replace('/[^a-z0-9]/i','',trim((string)$value)));foreach($courseOptions as $course){if($key===strtoupper(preg_replace('/[^a-z0-9]/i','',$course)))return $course;}
  $aliases=['IT'=>0,'BSIT'=>0,'INFORMATIONTECHNOLOGY'=>0,'CS'=>1,'BSCS'=>1,'COMPUTERSCIENCE'=>1,'IS'=>2,'BSIS'=>2,'INFORMATIONSYSTEMS'=>2,'BSBA'=>3,'BUSINESSADMINISTRATION'=>3,'BSA'=>4,'ACCOUNTANCY'=>4,'BSHM'=>5,'HOSPITALITYMANAGEMENT'=>5,'BSTM'=>6,'TOURISMMANAGEMENT'=>6,'BSED'=>7,'EDUCATION'=>7,'BEED'=>8,'ELEMENTARYEDUCATION'=>8,'CRIM'=>9,'BSCRIM'=>9,'CRIMINOLOGY'=>9];return isset($aliases[$key])?$courseOptions[$aliases[$key]]:trim((string)$value);
}
function student_import_year($value){$key=strtoupper(preg_replace('/\s+/','',trim((string)$value)));$years=['1STYEAR'=>'1st Year','1YEAR'=>'1st Year','1'=>'1st Year','1ST'=>'1st Year','2NDYEAR'=>'2nd Year','2YEAR'=>'2nd Year','2'=>'2nd Year','2ND'=>'2nd Year','3RDYEAR'=>'3rd Year','3YEAR'=>'3rd Year','3'=>'3rd Year','3RD'=>'3rd Year','4THYEAR'=>'4th Year','4YEAR'=>'4th Year','4'=>'4th Year','4TH'=>'4th Year'];return $years[$key]??trim((string)$value);}
function student_import_headers($headers){
  $aliases=['student_no'=>['student_no','student_id','id_number'],'first_name'=>['first_name','firstname','given_name'],'middle_name'=>['middle_name','middle_initial','mi'],'last_name'=>['last_name','lastname','surname','family_name'],'course'=>['course','strand','course_strand'],'year_level'=>['year_level','year','grade','grade_level'],'section'=>['section','block'],'email'=>['email','email_address'],'contact_number'=>['contact_number','contact','phone','mobile'],'qr_code'=>['qr_code','barcode','qr'],'account_status'=>['account_status','status'],'full_name'=>['full_name','name','student_name']];
  $map=[];foreach($headers as $index=>$header){$key=strtolower(preg_replace('/[^a-z0-9]+/i','_',trim((string)$header)));$key=trim($key,'_');foreach($aliases as $field=>$names){if(in_array($key,$names,true)){$map[$field]=$index;break;}}}return $map;
}
function student_import_row($values,$map){
  $row=[];foreach(['student_no','first_name','middle_name','last_name','course','year_level','section','email','contact_number','qr_code','account_status'] as $field){$row[$field]=isset($map[$field])?student_import_value($values[$map[$field]]??''):'';}
  if(($row['first_name']===''||$row['last_name']==='')&&isset($map['full_name'])){$parts=preg_split('/\s+/',student_import_value($values[$map['full_name']]??''),-1,PREG_SPLIT_NO_EMPTY);if(count($parts)>=2){$row['first_name']=array_shift($parts);$row['last_name']=array_pop($parts);if($row['middle_name']===''&&$parts)$row['middle_name']=substr($parts[0],0,1);}}
  $row['first_name']=format_student_name($row['first_name']);$row['last_name']=format_student_name($row['last_name']);$middleLetters=preg_replace('/[^a-zA-Z]/','',$row['middle_name']);$row['middle_name']=strtoupper(substr($middleLetters,0,1));$row['course']=student_import_course($row['course'], $GLOBALS['courseOptions']);$row['year_level']=student_import_year($row['year_level']);if($row['qr_code']===''&&$row['student_no']!=='')$row['qr_code']=$row['student_no'];$row['account_status']=strtoupper($row['account_status']?:'ACTIVE');return $row;
}
function student_import_sql_tuples($text){
  $tuples=[];$length=strlen($text);$index=0;while($index<$length){while($index<$length&&(ctype_space($text[$index])||$text[$index]===','))$index++;if($index>=$length)break;if($text[$index]!=='(')return [];$index++;$values=[];$value='';$quoted=false;$wasQuoted=false;
    while($index<$length){$char=$text[$index++];if($quoted){if($char==='\\'&&$index<$length){$next=$text[$index++];$value.=($next==='n'?"\n":($next==='r'?"\r":$next));}elseif($char==="'"){if($index<$length&&$text[$index]==="'"){$value.="'";$index++;}else{$quoted=false;}}else{$value.=$char;}continue;}
      if($char==="'"){$quoted=true;$wasQuoted=true;continue;}if($char===','){$values[]=$wasQuoted?$value:(strcasecmp(trim($value),'NULL')===0?'':trim($value));$value='';$wasQuoted=false;continue;}if($char===')'){$values[]=$wasQuoted?$value:(strcasecmp(trim($value),'NULL')===0?'':trim($value));$tuples[]=$values;break;}$value.=$char;
    }
    if($quoted||$index>$length)return [];
  }return $tuples;
}
function student_import_parse_sql($contents){
  preg_match_all('/INSERT\s+INTO\s+`?students`?\s*(?:\(([^)]*)\))?\s*VALUES\s*(.*?);/is',$contents,$matches,PREG_SET_ORDER);$rows=[];
  $defaultColumns=['id','student_no','first_name','last_name','middle_name','course','year_level','section','email','contact_number','qr_code','account_status','created_at','updated_at'];
  foreach($matches as $match){$columnList=trim($match[1]??'');$columns=$columnList!==''?array_map(function($column){return trim($column," `\t\r\n");},explode(',',$columnList)):$defaultColumns;$map=student_import_headers($columns);foreach(student_import_sql_tuples($match[2]) as $values){if(count($values)===count($columns))$rows[]=student_import_row($values,$map);}}
  return $rows;
}
function student_import_validate($row,$courseOptions,$yearOptions){
  $errors=[];foreach(['student_no'=>'Student ID','first_name'=>'First name','last_name'=>'Last name','qr_code'=>'QR/barcode'] as $field=>$label){if($row[$field]==='')$errors[]=$label.' is required.';}
  if($row['middle_name']!==''&&!preg_match('/^[A-Z]$/',$row['middle_name']))$errors[]='Middle initial must be one uppercase letter.';
  if($row['course']===''||(!in_array($row['course'],$courseOptions,true)&&strlen($row['course'])>100))$errors[]='Course is required and must be at most 100 characters.';
  if(!in_array($row['year_level'],$yearOptions,true))$errors[]='Year level must be 1st Year, 2nd Year, 3rd Year, or 4th Year.';
  if($row['contact_number']!==''&&!preg_match('/^\d{11}$/',$row['contact_number']))$errors[]='Contact number must contain exactly 11 digits.';
  if($row['email']!==''&&!filter_var($row['email'],FILTER_VALIDATE_EMAIL))$errors[]='Email address is invalid.';
  if(!in_array($row['account_status'],['ACTIVE','INACTIVE'],true))$errors[]='Status must be ACTIVE or INACTIVE.';
  if(strlen($row['student_no'])>50||strlen($row['first_name'])>100||strlen($row['last_name'])>100||strlen($row['middle_name'])>100||strlen($row['course'])>100||strlen($row['year_level'])>20||strlen($row['section'])>50||strlen($row['email'])>150||strlen($row['contact_number'])>40||strlen($row['qr_code'])>255)$errors[]='One or more values exceed the database field limit.';
  return $errors;
}
if(empty($_SESSION['student_import_csrf']))$_SESSION['student_import_csrf']=bin2hex(random_bytes(32));
if(isset($_GET['discard_import'])){$savedPreview=$_SESSION['student_import_preview']??null;if($savedPreview&&hash_equals($savedPreview['token'],(string)$_GET['discard_import']))unset($_SESSION['student_import_preview']);header('Location: students.php');exit;}
if(isset($_POST['import_action'])&&!isset($_POST['action']))$_POST['action']=$_POST['import_action'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['first_name']))$_POST['first_name']=format_student_name($_POST['first_name']);if(isset($_POST['last_name']))$_POST['last_name']=format_student_name($_POST['last_name']);}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['course']??'')==='Other' && trim($_POST['custom_course']??'')===''){ http_response_code(422); exit('Please enter the custom Course.'); }
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['course']??'')==='Other' && trim($_POST['custom_course']??'')!==''){$courseOptions[]=trim($_POST['custom_course']);$_POST['course']=trim($_POST['custom_course']);}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['middle_name']) && $_POST['middle_name']!=='' && !preg_match('/^[A-Z]$/',$_POST['middle_name'])){ http_response_code(422); exit('Middle Initial must be one uppercase letter.'); }
if(isset($_GET['export'])){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename=students.csv');echo "student_id,full_name,course,grade,section,email,contact,qr_code,status\n";$r=$conn->query('SELECT * FROM students ORDER BY last_name,first_name');while($s=$r->fetch_assoc()){echo implode(',',array_map(function($v){return '"'.str_replace('"','""',(string)$v).'"';},[$s['student_no'],$s['first_name'].' '.$s['last_name'],$s['course'],$s['year_level'],$s['section'],$s['email'],$s['contact_number'],$s['qr_code'],$s['account_status']]))."\n";}exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&in_array($_POST['action']??'', ['import_preview','import_commit'],true)){
  if(!hash_equals($_SESSION['student_import_csrf'],(string)($_POST['csrf_token']??''))){http_response_code(403);$error='Import session expired. Reload the page and try again.';}
  elseif($_POST['action']==='import_preview'){
    $file=$_FILES['student_file']??null;$extension=strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION));$previewRows=[];
    if(!$file){$error='Choose a CSV or SQL file to upload.';}
    elseif($file['error']===UPLOAD_ERR_INI_SIZE||$file['error']===UPLOAD_ERR_FORM_SIZE){$error='The file exceeds the server upload limit. Choose a smaller file or ask the server administrator to raise the upload limit.';}
    elseif($file['error']!==UPLOAD_ERR_OK){$error='The file upload did not complete. Please choose the file again and retry.';}
    elseif($file['size']>5*1024*1024){$error='The file must be 5 MB or smaller.';}
    elseif($file['size']===0){$error='The selected file is empty.';}
    elseif(!in_array($extension,['csv','sql'],true)){$error='Upload a CSV file or a SQL dump containing INSERT INTO students statements.';}
    else{$contents=file_get_contents($file['tmp_name']);if($extension==='sql'){$previewRows=student_import_parse_sql($contents);}else{$stream=fopen($file['tmp_name'],'r');$headers=$stream?fgetcsv($stream,0,',','"','\\'):false;if($headers){$headers[0]=preg_replace('/^\xEF\xBB\xBF/','',(string)$headers[0]);$map=student_import_headers($headers);while(($values=fgetcsv($stream,0,',','"','\\'))!==false){if(count(array_filter($values,function($value){return trim((string)$value)!=='';}))>0)$previewRows[]=student_import_row($values,$map);}}if($stream)fclose($stream);}
      if(!$previewRows){$error='No student data rows were found. Check the file headers or SQL INSERT format.';}else{$seenStudent=[];$seenQr=[];foreach($previewRows as $index=>$row){$issues=student_import_validate($row,$courseOptions,$yearOptions);$studentKey=strtolower($row['student_no']);$qrKey=strtolower($row['qr_code']);$duplicate=($studentKey!==''&&isset($seenStudent[$studentKey]))||($qrKey!==''&&isset($seenQr[$qrKey]));if($duplicate)$issues[]='Duplicate Student ID or QR/barcode within this file.';if($studentKey!=='')$seenStudent[$studentKey]=true;if($qrKey!=='')$seenQr[$qrKey]=true;if(!$issues){$check=$conn->prepare('SELECT student_no,qr_code FROM students WHERE student_no=? OR qr_code=? LIMIT 1');$check->bind_param('ss',$row['student_no'],$row['qr_code']);$check->execute();if($check->get_result()->fetch_assoc())$issues[]='Duplicate Student ID or QR/barcode already registered.';}$previewRows[$index]['_issues']=$issues;$previewRows[$index]['_status']=$issues?(count(array_filter($issues,function($issue){return strpos($issue,'Duplicate')===0;}))?'duplicate':'invalid'):'ready';}
        $token=bin2hex(random_bytes(16));$_SESSION['student_import_preview']=['token'=>$token,'rows'=>$previewRows,'created'=>time()];$_SESSION['student_import_csrf']=bin2hex(random_bytes(32));$importPreview=$_SESSION['student_import_preview'];}}
  }else{$preview=$_SESSION['student_import_preview']??null;if(!$preview||!hash_equals($preview['token'],(string)($_POST['preview_token']??''))||time()-(int)$preview['created']>1800){$error='Import preview expired. Upload the file again.';unset($_SESSION['student_import_preview']);}else{$conn->begin_transaction();$added=0;$skipped=0;$failed=false;$insert=$conn->prepare('INSERT INTO students(student_no,first_name,last_name,middle_name,course,year_level,section,email,contact_number,qr_code,account_status) VALUES(?,?,?,?,?,?,?,?,?,?,?)');foreach($preview['rows'] as $row){if($row['_status']!=='ready')continue;$check=$conn->prepare('SELECT id FROM students WHERE student_no=? OR qr_code=? LIMIT 1');$check->bind_param('ss',$row['student_no'],$row['qr_code']);$check->execute();if($check->get_result()->fetch_assoc()){$skipped++;continue;}$insert->bind_param('sssssssssss',$row['student_no'],$row['first_name'],$row['last_name'],$row['middle_name'],$row['course'],$row['year_level'],$row['section'],$row['email'],$row['contact_number'],$row['qr_code'],$row['account_status']);try{$inserted=$insert->execute();}catch(PDOException $exception){if($exception->getCode()==='23505'){$skipped++;continue;}$failed=true;break;}if(!$inserted){$failed=true;break;}$added++;}
      if($failed){$conn->rollback();$error='Import stopped because a row could not be saved. No rows were committed.';}else{$conn->commit();$duplicates=count(array_filter($preview['rows'],function($row){return $row['_status']==='duplicate';}));$invalid=count(array_filter($preview['rows'],function($row){return $row['_status']==='invalid';}));$skipped+=$duplicates;$message="Import complete: $added registered, $skipped duplicate row(s) skipped, $invalid invalid row(s) not imported.";$admin=(int)($_SESSION['admin_id']??0);$log=$conn->prepare("INSERT INTO activity_logs(actor_type,actor_id,action,entity_type,details) VALUES('ADMIN',?,'Student bulk import','student',?)");$log->bind_param('is',$admin,$message);$log->execute();}unset($_SESSION['student_import_preview']);$_SESSION['student_import_csrf']=bin2hex(random_bytes(32));}}
}elseif($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='status'){
  $statusId=(int)($_POST['student_id']??0);$status=($_POST['account_status']??'ACTIVE')==='INACTIVE'?'INACTIVE':'ACTIVE';
  $statusStatement=$conn->prepare('UPDATE students SET account_status=? WHERE id=?');$statusStatement->bind_param('si',$status,$statusId);$ok=$statusStatement->execute();$message=$ok?'Student status updated.':'Unable to update student status.';
}elseif($_SERVER['REQUEST_METHOD']==='POST'){
  $id=(int)($_POST['id']??0);$studentNo=trim($_POST['student_no']??'');$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');$middle=trim($_POST['middle_name']??'');$course=trim($_POST['course']??'');$grade=trim($_POST['grade']??'');$section=trim($_POST['section']??'');$email=trim($_POST['email']??'');$contact=trim($_POST['contact_number']??'');$qr=trim($_POST['qr_code']??'');$status=($_POST['account_status']??'ACTIVE')==='INACTIVE'?'INACTIVE':'ACTIVE';
  if(!$studentNo||!$first||!$last||!$qr){$error='Scan a QR/Barcode and complete Student ID, First Name, and Last Name.';}elseif($contact!==''&&!preg_match('/^\d{11}$/',$contact)){$error='Contact Number must contain exactly 11 digits.';}elseif(!in_array($course,$courseOptions,true)){$error='Please select a valid Course / Strand.';}elseif(!in_array($grade,$yearOptions,true)){$error='Please select a valid Year Level.';}elseif($id){$s=$conn->prepare('UPDATE students SET student_no=?,first_name=?,last_name=?,middle_name=?,course=?,year_level=?,section=?,email=?,contact_number=?,qr_code=?,account_status=? WHERE id=?');$s->bind_param('sssssssssssi',$studentNo,$first,$last,$middle,$course,$grade,$section,$email,$contact,$qr,$status,$id);$ok=$s->execute();$message=$ok?'Student record updated.':'Unable to update student. Student ID or QR may already exist.';}else{$s=$conn->prepare('INSERT INTO students(student_no,first_name,last_name,middle_name,course,year_level,section,email,contact_number,qr_code,account_status) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->bind_param('sssssssssss',$studentNo,$first,$last,$middle,$course,$grade,$section,$email,$contact,$qr,$status);$ok=$s->execute();$message=$ok?'Student registered successfully.':'Unable to add student. Student ID or QR may already exist.';}
  if(!empty($ok)&&$ok){$log=$conn->prepare("INSERT INTO activity_logs(actor_type,actor_id,action,entity_type,entity_id,details) VALUES('ADMIN',?,'Student modification','student',?,?)");$admin=(int)($_SESSION['admin_id']??0);$log->bind_param('iis',$admin,$id,$message);$log->execute();}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='import_preview'&&($_POST['ajax']??'')==='1'){header('Content-Type: application/json; charset=utf-8');if($error){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$error]);}else{echo json_encode(['ok'=>true,'token'=>$_SESSION['student_import_preview']['token']??'']);}exit;}
$search=trim($_GET['search']??'');$like='%'.$search.'%';$q=$conn->prepare("SELECT * FROM students WHERE ?='' OR student_no LIKE ? OR first_name LIKE ? OR last_name LIKE ? OR course LIKE ? OR section LIKE ? ORDER BY last_name,first_name");$q->bind_param('ssssss',$search,$like,$like,$like,$like,$like);$q->execute();$rows=$q->get_result();$pageTitle='Students - Admin';$importPreview=$importPreview??null;$savedPreview=$_SESSION['student_import_preview']??null;if(!$importPreview&&isset($_GET['show_import'],$savedPreview)&&hash_equals($savedPreview['token'],(string)$_GET['show_import'])&&time()-(int)$savedPreview['created']<=1800)$importPreview=$savedPreview;ob_start();
