td></tr><?php endforeach;?></tbody></table></div><div class="flex flex-wrap items-center justify-between gap-3 border-t p-4"><p class="text-sm text-slate-600">Duplicates and invalid rows are excluded. Ready rows can still be imported.</p><div class="flex gap-2"><a href="students.php" class="rounded border px-4 py-2 hover:bg-slate-50">Cancel</a><?php if($readyCount>0):?><form method="post"><input type="hidden" name="action" value="import_commit"><input type="hidden" name="csrf_token" value="<?php echo h($_SESSION['student_import_csrf']); ?>"><input type="hidden" name="preview_token" value="<?php echo h($importPreview['token']); ?>"><button class="rounded bg-emerald-700 px-4 py-2 font-semibold text-white hover:bg-emerald-600">Register <?php echo $readyCount; ?> students</button></form><?php endif;?></div></div></div></div>
