<script>(function(){var button=document.getElementById('studentImportButton'),file=document.getElementById('studentImportFile'),form=document.getElementById('studentImportForm'),loading=document.getElementById('studentImportLoading'),message=document.getElementById('studentImportLoadingMessage'),bar=document.getElementById('studentImportProgressBar'),progress=loading&&loading.querySelector('[role="progressbar"]'),percent=document.getElementById('studentImportProgressText');if(!button||!file||!form)return;var busy=false;function setProgress(value){value=Math.max(1,Math.min(100,Math.round(value)));bar.style.width=value+'%';progress.setAttribute('aria-valuenow',String(value));percent.textContent=value+'%'}function estimateRows(contents,isSql){if(!isSql)return Math.max(1,contents.split(/\r\n|\n|\r/).filter(function(line){return line.trim()!==''}).length-1);var statements=contents.match(/INSERT\s+INTO\s+`?students`?\s*\([^)]*\)\s*VALUES/gi)||[];var tuples=(contents.match(/\)\s*,\s*\(/g)||[]).length;return Math.max(1,statements.length+tuples)}button.addEventListener('click',function(){file.click()});file.addEventListener('change',async function(){if(!file.files.length||busy)return;busy=true;button.disabled=true;loading.classList.remove('hidden');loading.classList.add('flex');setProgress(1);try{var selected=file.files[0],contents=await selected.text(),rowCount=estimateRows(contents,/\.sql$/i.test(selected.name));message.textContent='Uploading and checking '+rowCount+' student row'+(rowCount===1?'':'s')+'...';var request=new XMLHttpRequest(),processingTimer;request.open('POST',form.action||window.location.href);request.upload.addEventListener('progress',function(event){if(event.lengthComputable)setProgress(Math.max(1,Math.min(70,event.loaded/event.total*70)))});request.upload.addEventListener('load',function(){setProgress(Math.max(70,Number(progress.getAttribute('aria-valuenow'))));message.textContent='Checking '+rowCount+' student row'+(rowCount===1?'':'s')+' for valid data and duplicates...';var started=Date.now(),estimatedMs=Math.min(15000,Math.max(700,rowCount*6));processingTimer=window.setInterval(function(){setProgress(72+Math.min(26,(Date.now()-started)/estimatedMs*26))},100)});request.addEventListener('load',function(){window.clearInterval(processingTimer);var result;try{result=JSON.parse(request.responseText)}catch(error){result={ok:false,error:'The server returned an unreadable response. Please try again.'}}if(request.status<200||request.status>=300||!result.ok){loading.classList.add('hidden');loading.classList.remove('flex');busy=false;button.disabled=false;file.value='';window.alert(result.error||'Unable to check the uploaded file.');return}setProgress(100);message.textContent='Check complete. Opening the data preview...';window.setTimeout(function(){window.location.href='students.php?show_import='+encodeURIComponent(result.token)},300)});request.addEventListener('error',function(){window.clearInterval(processingTimer);loading.classList.add('hidden');loading.classList.remove('flex');busy=false;button.disabled=false;file.value='';window.alert('Network error while uploading student data.')});request.send(new FormData(form))}catch(error){loading.classList.add('hidden');loading.classList.remove('flex');busy=false;button.disabled=false;file.value='';window.alert('Unable to read the selected file. Please try again.')}})})();</script>
