<script>(function(){const hidden=document.getElementById('qrHidden'),frame=document.getElementById('frame'),status=document.getElementById('scanStatus'),modal=document.getElementById('registerModal'),search=document.getElementById('studentSearch'),searchForm=document.getElementById('studentSearchForm'),cancel=document.getElementById('cancelRegister'),confirm=document.getElementById('confirmRegister');let timer,pending='';function focus(){if(hidden&&!hidden.disabled&&document.activeElement!==hidden)hidden.focus()}function fail(text){status.textContent=text;frame.classList.add('shake');setTimeout(()=>frame.classList.remove('shake'),400)}function close(){modal.classList.add('hidden');modal.classList.remove('flex');hidden.disabled=false;pending='';focus()}async function lookup(code){status.textContent='Checking Student ID...';try{const response=await fetch('../api/check_student.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({qr:code})});const result=await response.json();if(!result.ok){fail(result.error||'Unable to check Student ID.');return}if(result.exists){modal.classList.add('hidden');modal.classList.remove('flex');search.value=result.student.student_no||code;searchForm.submit();return}pending=code;status.textContent='Student ID not found. Choose an option.';hidden.disabled=true;modal.classList.remove('hidden');modal.classList.add('flex')}catch(error){fail('Network error while checking the Student ID.')}}function scan(){const code=hidden.value.trim();hidden.value='';if(code)lookup(code)}window.addEventListener('keydown',function(event){if(event.target!==hidden||hidden.disabled)return;event.stopImmediatePropagation();if(event.key==='Enter'){event.preventDefault();scan()}},{capture:true});window.addEventListener('input',function(event){if(event.target!==hidden||hidden.disabled)return;event.stopImmediatePropagation();clearTimeout(timer);timer=setTimeout(()=>{if(hidden.value.trim())scan()},180)},{capture:true});cancel.addEventListener('click',close);confirm.addEventListener('click',function(){const code=pending;close();document.getElementById('qrCode').value=code;document.getElementById('studentNoDisplay').value=code;document.getElementById('formCard').classList.remove('hidden');document.getElementById('firstName').focus()});setInterval(focus,500);focus()})();</script>
<script>(function(){const cancel=document.getElementById('cancelRegister'),confirm=document.getElementById('confirmRegister'),hidden=document.getElementById('qrHidden'),status=document.getElementById('scanStatus');cancel.addEventListener('click',function(){hidden.value='';hidden.disabled=true;status.textContent='Scan cancelled. Press the camera button or Scan Again to start a new scan.';hidden.blur()});confirm.addEventListener('click',function(){document.getElementById('qrDisplay').value=document.getElementById('qrCode').value||document.getElementById('studentNoDisplay').value})})();</script>
<script>(function(){const hidden=document.getElementById('qrHidden'),frame=document.getElementById('frame'),msg=document.getElementById('scanMsg'),status=document.getElementById('scanStatus'),card=document.getElementById('formCard');let timer;function keepFocus(){if(hidden&&!hidden.disabled&&document.activeElement!==hidden)hidden.focus()}function fail(text){status.textContent=text;frame.classList.add('shake');setTimeout(()=>frame.classList.remove('shake'),400)}async function submitCode(code){if(!code)return;status.textContent='Checking QR / Barcode...';try{const r=await fetch('../api/check_student.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({qr:code})});const j=await r.json();if(!j.ok){fail(j.error||'Invalid scan.');return}const s=j.student;document.getElementById('studentId').value=s.id||'';document.getElementById('qrCode').value=s.qr_code||code;document.getElementById('studentNoDisplay').value=s.student_no||code;document.getElementById('qrDisplay').value=s.qr_code||code;document.getElementById('firstName').value=s.first_name||'';document.getElementById('middleName').value=s.middle_name||'';document.getElementById('lastName').value=s.last_name||'';document.getElementById('grade').value=s.course||'';document.getElementById('section').value=s.section||'';document.getElementById('email').value=s.email||'';document.getElementById('contact').value=s.contact_number||'';document.getElementById('accountStatus').value=s.account_status||'ACTIVE';msg.textContent=j.exists?'Student found':'QR detected';status.textContent=j.message;card.classList.remove('hidden');hidden.disabled=true;window.scrollTo({top:card.offsetTop-20,behavior:'smooth'});document.getElementById('firstName').focus()}catch(e){fail('Network error while checking the scan.')}}function enter(){const code=hidden.value.trim();hidden.value='';if(code)submitCode(code)}hidden.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();enter()}});hidden.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(hidden.value.trim())enter()},180)});document.getElementById('rescan').addEventListener('click',()=>{card.classList.add('hidden');hidden.disabled=false;msg.textContent='Waiting for QR scan...';status.textContent='Focus is locked to scanner input.';keepFocus()});setInterval(keepFocus,500);keepFocus()})();</script>
<script>(function(){document.querySelectorAll('select[name="account_status"]').forEach(function(select){var wrapper=document.createElement('span');wrapper.className='inline-flex items-center gap-1';var label=document.createElement('span');label.className='min-w-16 text-center font-semibold text-xs';var arrowControl=document.createElement('span');arrowControl.className='inline-flex flex-col overflow-hidden rounded border border-slate-300 bg-white shadow-sm';var up=document.createElement('button');var down=document.createElement('button');up.type='button';down.type='button';up.className='flex h-5 w-7 items-center justify-center p-0 text-[10px] leading-none text-slate-600 transition hover:bg-slate-100 hover:text-indigo-700 active:bg-indigo-100';down.className='flex h-5 w-7 items-center justify-center border-t border-slate-200 p-0 text-[10px] leading-none text-slate-600 transition hover:bg-slate-100 hover:text-indigo-700 active:bg-indigo-100';up.textContent='▲';down.textContent='▼';up.title='Select status above';down.title='Select status below';function refresh(){label.textContent=select.value;label.className='min-w-16 text-center text-xs font-semibold '+(select.value==='ACTIVE'?'text-emerald-700':'text-rose-700')}function move(step){var next=select.selectedIndex+step;if(next<0)next=select.options.length-1;if(next>=select.options.length)next=0;select.selectedIndex=next;refresh()}up.addEventListener('click',function(){move(-1)});down.addEventListener('click',function(){move(1)});select.classList.add('hidden');arrowControl.append(up,down);wrapper.append(label,arrowControl);select.parentElement.appendChild(wrapper);refresh()})})();</script>
<script>(function(){var table=document.querySelector('tbody#studentRows')||document.querySelector('.overflow-x-auto table tbody');if(!table)return;var header=table.parentElement.querySelector('thead tr');var actionHeader=document.createElement('th');actionHeader.className='px-2 py-2';actionHeader.textContent='Action';header.appendChild(actionHeader);function fill(student,code){document.getElementById('studentId').value=student.id||'';document.getElementById('qrCode').value=student.qr_code||code;document.getElementById('studentNoDisplay').value=student.student_no||code;document.getElementById('qrDisplay').value=student.qr_code||code;document.getElementById('firstName').value=student.first_name||'';document.getElementById('middleName').value=student.middle_name||'';document.getElementById('lastName').value=student.last_name||'';document.getElementById('grade').value=student.course||'';document.getElementById('section').value=student.section||'';document.getElementById('email').value=student.email||'';document.getElementById('contact').value=student.contact_number||'';document.getElementById('accountStatus').value=student.account_status||'ACTIVE';document.getElementById('studentDetailsTitle').textContent='Edit Student Details';document.getElementById('formCard').classList.remove('hidden');var hidden=document.getElementById('qrHidden');if(hidden){hidden.disabled=true;hidden.blur()}document.getElementById('firstName').focus()}Array.prototype.slice.call(table.querySelectorAll('tr')).forEach(function(row){var cells=row.children;if(!cells.length)return;var code=cells[0].textContent.trim();var cell=document.createElement('td');cell.className='px-2 py-3';var button=document.createElement('button');button.type='button';button.className='rounded bg-indigo-600 px-3 py-1 text-xs font-semibold text-white hover:bg-indigo-500';button.textContent='Edit';button.addEventListener('click',function(){button.disabled=true;button.textContent='Loading...';fetch('../api/check_student.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({qr:code})}).then(function(response){return response.json()}).then(function(result){if(!result.ok||!result.exists)throw new Error(result.error||'Student record not found.');fill(result.student,code)}).catch(function(error){window.alert(error.message||'Unable to load student record.')}).finally(function(){button.disabled=false;button.textContent='Edit'})});cell.appendChild(button);row.appendChild(cell)})})();</script>
<script>(function(){var table=document.querySelector('tbody#studentRows')||document.querySelector('.overflow-x-auto table tbody');if(!table)return;Array.prototype.slice.call(table.querySelectorAll('tr')).forEach(function(row){var form=row.querySelector('form');if(!form)return;var select=form.querySelector('select[name="account_status"]');var cell=form.closest('td');var status=select?select.value:'ACTIVE';cell.innerHTML='<span class="rounded-full px-2 py-1 text-xs font-semibold '+(status==='ACTIVE'?'bg-emerald-100 text-emerald-700':'bg-rose-100 text-rose-700')+'">'+status+'</span>'})})();</script>
<script>(function(){var grade=document.getElementById('grade'),form=document.getElementById('studentForm'),card=document.getElementById('formCard');if(!grade||!form||!card)return;var course=document.createElement('input');course.name='course';course.id='course';course.placeholder='Course / Strand';course.className=grade.className;grade.parentNode.insertBefore(course,grade);var originalFetch=window.fetch;window.fetch=function(){return originalFetch.apply(this,arguments).then(function(response){if(!String(arguments[0]||'').includes('check_student.php'))return response;return response.clone().json().then(function(data){if(data.student&&data.student.year_level!==undefined)data.student.course=(data.student.course||'')+'||'+(data.student.year_level||'');return new Response(JSON.stringify(data),{status:response.status,headers:{'Content-Type':'application/json'}})})})};function sync(){if(card.classList.contains('hidden')||!document.getElementById('studentId').value)return;var value=grade.value;if(value.indexOf('||')>=0){var parts=value.split('||');course.value=parts[0];grade.value=parts[1]||'';}else if(!course.value&&value){course.value=value;grade.value='';}}new MutationObserver(sync).observe(card,{attributes:true,attributeFilter:['class']});form.addEventListener('submit',function(){if(!course.value&&grade.value)course.value=grade.value;});})();</script>
<script>(function(){var base=window.fetch;window.fetch=function(){var url=arguments[0];return base.apply(this,arguments).then(function(response){if(!String(url||'').includes('check_student.php'))return response;return response.clone().json().then(function(data){if(data.student&&data.student.year_level!==undefined)data.student.course=(data.student.course||'')+'||'+(data.student.year_level||'');return new Response(JSON.stringify(data),{status:response.status,headers:{'Content-Type':'application/json'}})})})};})();</script>
<script>(function(){var contact=document.getElementById('contact'),middle=document.getElementById('middleName'),first=document.getElementById('firstName'),last=document.getElementById('lastName');if(contact)contact.addEventListener('input',function(){contact.value=contact.value.replace(/\D/g,'').slice(0,11)});if(middle){middle.maxLength=1;middle.pattern='[A-Z]';middle.title='Enter one uppercase middle initial';middle.placeholder='Middle Initial';middle.addEventListener('input',function(){middle.value=middle.value.replace(/[^a-zA-Z]/g,'').slice(0,1).toUpperCase()})}function capitalizeName(field){if(!field)return;field.value=field.value.toLowerCase().replace(/(^|[\s-])([a-z])/g,function(match,separator,letter){return separator+letter.toUpperCase()})}if(first)first.addEventListener('input',function(){capitalizeName(first)});if(last)last.addEventListener('input',function(){capitalizeName(last)})})();</script>
<script>(function(){var section=document.getElementById('section'),search=document.getElementById('studentSearch'),heading=document.querySelector('#studentSearchForm + .overflow-x-auto thead th:nth-child(5)'),course=document.getElementById('course'),year=document.getElementById('grade');if(section){section.placeholder='Block';section.setAttribute('aria-label','Block')}if(search)search.placeholder='Search Student ID, Name, Course, Year Level, Block';if(heading)heading.textContent='Block';if(course){course.setAttribute('aria-label','Course');course.options[0].textContent='Course'}if(year){year.setAttribute('aria-label','Year Level');year.options[0].textContent='Year Level'}})();</script>
<script>(function(){var formCard=document.getElementById('formCard'),course=document.getElementById('course'),year=document.getElementById('grade');if(!formCard||!course||!year)return;document.querySelectorAll('#course').forEach(function(field,index){if(index>0)field.remove()});function sync(){var value=year.value||'';if(value.indexOf('||')>=0){var parts=value.split('||');course.value=parts[0];year.value=parts[1]||'';}else if(!yearOptionsValue(value)&&course.value===''){course.value=value;year.value='';}}function yearOptionsValue(value){return ['1st Year','2nd Year','3rd Year','4th Year'].indexOf(value)>=0}new MutationObserver(sync).observe(formCard,{attributes:true,attributeFilter:['class']});sync()})();</script>
<script>(function(){var course=document.getElementById('course'),form=document.getElementById('studentForm');if(!course||!form)return;var custom=document.createElement('input');custom.type='text';custom.name='custom_course';custom.id='customCourse';custom.maxLength=120;custom.placeholder='Enter Course';custom.className=course.className+' hidden';custom.setAttribute('aria-label','Custom Course');course.parentNode.insertBefore(custom,course.nextSibling);function sync(){var isOther=course.value==='Other';custom.classList.toggle('hidden',!isOther);custom.required=isOther;if(!isOther)custom.value='';}course.addEventListener('change',sync);form.addEventListener('submit',function(event){if(course.value==='Other'){if(!custom.value.trim()){event.preventDefault();custom.focus();return}var option=Array.prototype.slice.call(course.options).find(function(item){return item.value===custom.value.trim()});if(!option){option=document.createElement('option');option.value=custom.value.trim();option.textContent=custom.value.trim();course.appendChild(option)}course.value=option.value}});sync()})();</script>
